function monthsToGoal(C0, m, r, goal){
  var rm=r/12;
  if(rm===0){ if(m<=0) return null; return (goal-C0)/m; }
  var a=1+rm, base=C0 + m/rm;
  if(base<=0) return null;
  return Math.log((goal + m/rm)/base)/Math.log(a);
}
function requiredMonthly(C0, r, months, goal){
  var rm=r/12;
  if(rm===0) return (goal-C0)/months;
  var a=Math.pow(1+rm, months);
  return (goal - C0*a)*rm/(a-1);
}
var EXPORTS={monthsToGoal:monthsToGoal, requiredMonthly:requiredMonthly};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SavingsGoalForgePure = EXPORTS; }
